function queryArticleContent(){var n=getUrlParameter("articleId");$.ajax({async:!1,url:"/WeixinService/article/queryArticleContent.xhtml",data:{articleId:n},dataType:"json",cache:!1,type:"post",error:function(){},success:function(n){var t="";t+="<div class='box-news'>";t+="<h2>";t+="<span>"+(typeof n.title=="undefined"?"":n.title)+"<\/span>";t+="<i>"+(typeof n.publishDate=="undefined"?"":n.publishDate)+"<\/i>";t+="<\/h2>";t+="<div class='box-news-detail'>"+(typeof n.content=="undefined"?"":n.content);t+="<\/div>";t+="<\/div>";$("#articleDetail").html(t);myScroll.refresh()}})}$(document).ready(function(){var n="1"==getUrlParameter("type")?"新闻动态":"最新公告";$(".header .top-a h2").html(n);document.title=n;myScroll=new IScroll("#wrapper",{scrollbars:!0,mouseWheel:!0,interactiveScrollbars:!0,shrinkScrollbars:"scale",fadeScrollbars:!0});queryArticleContent();getUserRequest("article-content")});document.addEventListener("touchmove",function(n){n.preventDefault()},!1)